package com.sih.netrasahayak.ml

import com.google.gson.JsonObject
import com.google.gson.JsonParser
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.zip.GZIPInputStream

/**
 * Pins the Kotlin preprocessing + quality gate to the Python reference
 * (ml/netra_ml/preprocess.py, quality.py). Golden files are generated by
 * `python -m netra_ml.golden --out app/src/test/resources/golden`.
 */
class GoldenParityTest {

    private fun resource(name: String) =
        requireNotNull(javaClass.classLoader!!.getResourceAsStream("golden/$name")) { "missing golden/$name" }

    private fun cases(): List<String> = resource("cases.txt").bufferedReader().readLines().filter { it.isNotBlank() }

    private fun gz(name: String): ByteArray = GZIPInputStream(resource(name)).use { it.readBytes() }

    /** Decoded input pixels, written by the Python reference. */
    private fun loadInput(name: String): RgbImage {
        val m = meta(name)
        return RgbImage(m["width"].asInt, m["height"].asInt, gz("${name}_input.rgb.gz"))
    }

    private fun meta(name: String): JsonObject =
        JsonParser.parseReader(resource("$name.json").bufferedReader()).asJsonObject

    @Test
    fun goldenCasesExist() {
        assertTrue(cases().size >= 4)
    }

    @Test
    fun preprocessingMatchesPythonReferenceExactly() {
        for (name in cases()) {
            val m = meta(name)
            if (m.get("geometry").isJsonNull) continue
            val pre = RetinaPreprocessor.preprocess(loadInput(name))
            val expected = gz("${name}_expected.rgb.gz")
            assertEquals("$name size", expected.size, pre.image.data.size)
            var mismatches = 0
            var maxDiff = 0
            for (i in expected.indices) {
                val d = kotlin.math.abs((expected[i].toInt() and 0xFF) - (pre.image.data[i].toInt() and 0xFF))
                if (d != 0) mismatches++
                if (d > maxDiff) maxDiff = d
            }
            assertTrue("$name: max pixel difference $maxDiff", maxDiff <= 1)
            assertTrue("$name: $mismatches differing values", mismatches <= expected.size / 1000)

            val g = m.getAsJsonObject("geometry")
            assertEquals(g["top"].asInt, pre.geometry.top)
            assertEquals(g["left"].asInt, pre.geometry.left)
            assertEquals(g["bbox_height"].asInt, pre.geometry.bboxHeight)
            assertEquals(g["bbox_width"].asInt, pre.geometry.bboxWidth)
            assertEquals(g["work_width"].asInt, pre.geometry.workWidth)
        }
    }

    @Test
    fun qualityGateMatchesPythonReference() {
        for (name in cases()) {
            val m = meta(name)
            val result = ImageQualityAssessor.assess(loadInput(name))
            assertEquals("$name status", m["status"].asString, result.status.name)
            assertEquals("$name reasons", m["reasons"].asJsonArray.map { it.asString }, result.reasons)
            if (!m.get("metrics").isJsonNull) {
                val e = m.getAsJsonObject("metrics")
                val a = assertNotNull(result.metrics).let { result.metrics!! }
                assertEquals(e["retina_fraction"].asDouble, a.retinaFraction, 1e-9)
                assertEquals(e["corner_dark_fraction"].asDouble, a.cornerDarkFraction, 1e-9)
                assertEquals(e["red_ratio"].asDouble, a.redRatio, 1e-6)
                assertEquals(e["mean_brightness"].asDouble, a.meanBrightness, 1e-6)
                assertEquals(e["saturated_fraction"].asDouble, a.saturatedFraction, 1e-9)
                assertEquals(e["sharpness"].asDouble, a.sharpness, 1e-3 * maxOf(1.0, e["sharpness"].asDouble))
            }
        }
    }
}
